// carts/jetchess/art/palette.h
//
// The palette's names — generated by scripts/jetchess_art.py, which also
// writes data/palettes/jetchess.pal. Do not edit: edit the script, run it,
// and both files move together.
//
// Every index below is an entry of that file. The two ramps are runs: a ramp's
// name is its FIRST entry and it holds 12 in all, rim first and body last,
// which is also the order a soft edge crosses them.
#ifndef JETCHESS_ART_PALETTE_H
#define JETCHESS_ART_PALETTE_H

// The palette the cart loads in _init. It lives at data/palettes/<name>.pal.
#define JC_PALETTE_NAME "jetchess"

#define JC_VOID                      0 // the room the board stands in (and the transparency key)
#define JC_PANEL                     1 // the side panel's field
#define JC_PANEL_EDGE                2 // hairlines, dividers, an inset's rim and track
#define JC_PANEL_DEEP                3 // a well cut into the panel
#define JC_TEXT                      4 // text that must be read
#define JC_TEXT_DIM                  5 // text that may be read: a label, a value at rest
#define JC_TEXT_FAINT                6 // a button that cannot be used, and nothing else
#define JC_TEXT_GUTTER               7 // a move's number: one step down from the move itself
#define JC_CONTROL_EDGE              8 // a control's edge, and a section's tick
#define JC_BRASS                     9 // the accent: what you may do now, and what just happened
#define JC_BRASS_DIM                10 // the accent at rest
#define JC_ALERT                    11 // an alarm, said once
#define JC_ALERT_DEEP               12 // the check ring, against the check fill it sits on
#define JC_GOOD                     13 // a drawn or a won game
#define JC_INK                      14 // the white piece's rim, and every cut line
#define JC_BONE                     15 // the black piece's rim on a dark square
#define JC_BONE_QUIET               16 // ...and on a light square, where bone would vanish
#define JC_WHITE_PIECE              17 // the white piece's body, for the side-to-move mark
#define JC_BLACK_PIECE              18 // the black piece's body, likewise
#define JC_SQ_LIGHT                 19 // the light square
#define JC_SQ_DARK                  20 // the dark square
#define JC_CONTAINER_EDGE           21 // the hairline round the board and round the panel
#define JC_LIGHT_LAST               22 // where the last move came from, and went (light square)
#define JC_DARK_LAST                23 // where the last move came from, and went (dark square)
#define JC_LIGHT_CHECK              24 // the king that must answer (light square)
#define JC_DARK_CHECK               25 // the king that must answer (dark square)
#define JC_LIGHT_MATE               26 // ...and the king that could not (light square)
#define JC_DARK_MATE                27 // ...and the king that could not (dark square)
#define JC_LIGHT_HOVER              28 // the square under the pointer (light square)
#define JC_DARK_HOVER               29 // the square under the pointer (dark square)
#define JC_LIGHT_QUIET              30 // the board while it is not being played on (light square)
#define JC_DARK_QUIET               31 // the board while it is not being played on (dark square)
#define JC_LIGHT_LIFT               32 // the ground shadow under a held piece (light square)
#define JC_DARK_LIFT                33 // the ground shadow under a held piece (dark square)
#define JC_LIGHT_COORD              34 // the coordinate in a plain square's corner (light square)
#define JC_DARK_COORD               35 // the coordinate in a plain square's corner (dark square)
#define JC_LIGHT_COORDDEEP          36 // ...and in a marked or quiet one's (light square)
#define JC_DARK_COORDDEEP           37 // ...and in a marked or quiet one's (dark square)
#define JC_LIGHT_LASTQUIET          38 // where the last move went, on a quiet board (light square)
#define JC_DARK_LASTQUIET           39 // where the last move went, on a quiet board (dark square)
#define JC_SHADOW                   40 // the board's cast shadow, 6 entries from the room toward ink
#define JC_INK_HUSHED               46 // the white piece's rim, on a quiet board
#define JC_ALERT_MATE               47 // the ring round a mated king: the check ring, hushed
#define JC_BONE_HUSHED              48 // the black piece's rim, on a quiet DARK square
#define JC_BONE_QUIET_HUSHED        49 // ...and on a quiet LIGHT square, where the bright one would vanish
#define JC_WHITE_RAMP               50 // the white piece: 12 entries, ink rim to body
#define JC_BLACK_RAMP               62 // the black piece on a dark square: bone rim to body
#define JC_BLACK_QUIET_RAMP         74 // the black piece on a light square: a quieter rim to body
#define JC_WHITE_HUSHED_RAMP        86 // the white piece on a quiet board
#define JC_BLACK_HUSHED_RAMP        98 // the black piece on a quiet dark square
#define JC_BLACK_QUIET_HUSHED_RAMP 110 // the black piece on a quiet light square
#define JC_TYPE_RAMP_TEXT          122 // text that must be read: the panel, then 8 steps to its ink
#define JC_TYPE_RAMP_DIM           131 // a label, a value at rest: the panel, then 8 steps to its ink
#define JC_TYPE_RAMP_FAINT         140 // a button that cannot be used: the panel, then 8 steps to its ink
#define JC_TYPE_RAMP_GUTTER        149 // a move's number: the panel, then 8 steps to its ink
#define JC_TYPE_RAMP_BRASS         158 // the accent: the panel, then 8 steps to its ink

// How many entries a piece ramp holds, and the two the art itself uses:
// the body at the far end, every cut line at the near end (the rim).
#define JC_RAMP_STEPS 12
#define JC_RAMP_BODY 11
#define JC_RAMP_RIM 0
// How many entries the board's cast shadow holds, room-side first.
#define JC_SHADOW_STEPS 6
// How many steps a type ramp takes from the panel to its ink; a run holds
// one more, the panel itself. data/gfx/fonts.ron bakes every face to
// JC_TYPE_RAMP_TEXT's run alone (quantize_lo/hi), and jet_palette_ink_map
// re-voices it onto the others' (ui/ink.c).
#define JC_TYPE_RAMP_STEPS 8

// Entries 167 and up are unclaimed: room colour, and yours.
#define JC_PALETTE_USED 167

#endif // JETCHESS_ART_PALETTE_H
